package com.portfolio.fraud.fraud;
import com.portfolio.fraud.entity.*;
import com.portfolio.fraud.repository.TransactionRepository;
import java.math.BigDecimal; import java.time.*; import java.util.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class FraudDetectionService {
 private final TransactionRepository transactions; private final BigDecimal highValue,historicalMultiplier; private final int rapidMinutes,rapidCount,repeatCount;
 public FraudDetectionService(TransactionRepository t,@Value("${app.fraud.high-value}") BigDecimal h,@Value("${app.fraud.historical-multiplier}") BigDecimal hm,@Value("${app.fraud.rapid-window-minutes}") int m,@Value("${app.fraud.rapid-count}") int c,@Value("${app.fraud.repeat-count}") int r){transactions=t;highValue=h;historicalMultiplier=hm;rapidMinutes=m;rapidCount=c;repeatCount=r;}
 public Result evaluate(User user,Account sender,Account recipient,BigDecimal amount){List<Finding> f=new ArrayList<>();Instant since=Instant.now().minus(Duration.ofMinutes(rapidMinutes));if(amount.compareTo(highValue)>=0)f.add(new Finding("HIGH_VALUE","Amount exceeds configured high-value threshold",RiskLevel.HIGH,45));BigDecimal average=transactions.averageCompletedAmount(user.getId());if(average!=null&&average.signum()>0&&amount.compareTo(average.multiply(historicalMultiplier))>0)f.add(new Finding("UNUSUAL_AMOUNT","Amount materially exceeds the user's completed-transaction average",RiskLevel.HIGH,35));if(transactions.countByInitiatedByIdAndCreatedAtAfter(user.getId(),since)>=rapidCount)f.add(new Finding("RAPID_TRANSACTIONS","Several transactions were initiated in a short window",RiskLevel.MEDIUM,25));if(recipient!=null&&transactions.countBySenderAccountIdAndRecipientAccountIdAndCreatedAtAfter(sender.getId(),recipient.getId(),since)>=repeatCount)f.add(new Finding("REPEATED_TRANSFER","Repeated recipient transfer in a short window",RiskLevel.HIGH,35));if(sender.getBalance().subtract(amount).compareTo(amount.multiply(new BigDecimal("0.10")))<0)f.add(new Finding("BALANCE_RISK","Transfer leaves a disproportionately low balance",RiskLevel.MEDIUM,20));int score=Math.min(100,f.stream().mapToInt(Finding::points).sum());RiskLevel l=score>=80?RiskLevel.CRITICAL:score>=60?RiskLevel.HIGH:score>=30?RiskLevel.MEDIUM:RiskLevel.LOW;return new Result(score,l,f);}
 public record Finding(String rule,String reason,RiskLevel severity,int points){} public record Result(int score,RiskLevel level,List<Finding> findings){}
}
